using System.Text.Json.Serialization;

namespace GenerativeAI.Types;

/// <summary>
/// Represents a bidirectional response payload containing various types of server responses in a multimodal live session.
/// </summary>
public class LiveServerMessage
{
    /// <summary>
    /// Gets or sets a message sent in response to a <see cref="LiveClientSetup"/> message from the client.
    /// </summary>
    [JsonPropertyName("setupComplete")]
    public LiveServerSetupComplete? SetupComplete { get; set; }

    /// <summary>
    /// Gets or sets an incremental server update generated by the model in response to client messages.
    /// </summary>
    [JsonPropertyName("serverContent")]
    public LiveServerContent? ServerContent { get; set; }

    /// <summary>
    /// Gets or sets a request for the client to execute the <see cref="FunctionCall"/> and return the responses with the matching <see cref="FunctionCall.Id"/>.
    /// </summary>
    [JsonPropertyName("toolCall")]
    public LiveServerToolCall? ToolCall { get; set; }

    /// <summary>
    /// Gets or sets a notification for the client that a previously issued <see cref="LiveServerToolCall"/> with the specified ID should have been not executed and should be cancelled.
    /// </summary>
    [JsonPropertyName("toolCallCancellation")]
    public LiveServerToolCallCancellation? ToolCallCancellation { get; set; }
    
    /// <summary>
    /// Gets or sets a notification that server will disconnect soon.
    /// </summary>
    [JsonPropertyName("goAway")]
    public LiveServerGoAway? GoAway { get; set; }

    /// <summary>
    /// Gets or sets an update of the session resumption state.
    /// </summary>
    [JsonPropertyName("sessionResumptionUpdate")]
    public LiveServerSessionResumptionUpdate? SessionResumptionUpdate { get; set; }

    /// <summary>
    /// Gets or sets metadata about token usage for the current session.
    /// </summary>
    [JsonPropertyName("usageMetadata")]
    public UsageMetadata? UsageMetadata { get; set; }

    /// <summary>
    /// Gets or sets a voice activity detection signal. Allowlisted only.
    /// </summary>
    [JsonPropertyName("voiceActivityDetectionSignal")]
    public VoiceActivityDetectionSignal? VoiceActivityDetectionSignal { get; set; }

    /// <summary>
    /// Gets or sets a voice activity signal.
    /// </summary>
    [JsonPropertyName("voiceActivity")]
    public VoiceActivity? VoiceActivity { get; set; }
}